"use strict";(self.webpackChunkportfolio=self.webpackChunkportfolio||[]).push([[594],{3106:(e,t,a)=>{a.d(t,{A:()=>s});const i=[...[{id:"petsteps",name:"PetSteps",image:"/images/petsteps-hero.gif",description:"PetSteps is an iOS app that turns your daily steps into taking care of a virtual pet. You walk, your pet eats, levels up, and gets new outfits. It won Adobe's Digital Edge Standout Prize out of 2,400+ entries and was shown at Adobe MAX 2024. In 2026 I rebuilt the whole app on my own into something I would actually ship: step goals that adapt to your history from HealthKit, GPS route journaling, a spotlight onboarding tour, and a crayon art style built from hand drawn assets plus a script that generates the rest.",languages:["Swift","HealthKit","Apple Foundation Models","SwiftUI","SwiftData"],tagline:"Adobe Digital Edge Awards Winner",timeline:"2024 \xb7 revamp 2026",source:{label:"Code available upon request",href:"mailto:ximluo@upenn.edu?subject=PetSteps%20code%20request"},sections:[{text:"PetSteps won the Digital Edge Standout Prize at Adobe MAX 2024, picked from more than 2,400 entries. Adobe called out the originality, the execution, and the fact that the tech was pointed at an actual health goal, and later used the app in one of their marketing campaigns."},{image:"/images/adobe-max-2024.jpeg"},{text:"The loop is simple: your real steps pay for your pet's life. HealthKit and the motion coprocessor track what you actually walk, that turns into coins, coins buy food and accessories, feeding levels your pet up, and new levels unlock more gear and more pets. Start a walk and it records your route, live stats, and photos where your pet poses in the camera next to you. All of it ends up in a journal of routes, moods, and polaroids. There is also a coach you can chat with about your goals, running on device with Apple Foundation Models. The four main flows, left to right: the spotlight tour (feed, then level up), a walk with the in-walk camera, the journal, and the coach:"},{images:["/images/petsteps-flow-tour.gif","/images/petsteps-flow-walk.gif","/images/petsteps-flow-journal.gif","/images/petsteps-flow-coach.gif"]},{text:"Accessories don't just get pasted on at a fixed spot. I measured anchor points by hand on each species' artwork (top of the head, the eyes, the neck) and gave every accessory its own fit metadata, so the same cap sits between a cat's ears, on a retriever's brow, and on top of a puppy shaped like a sneaker. The sky is drawn in SwiftUI and shifts through dawn, day, dusk, and night, and once it gets dark the rest of the app switches to night colors with it. Same four outfits at four times of day:"},{images:["/images/petsteps-otd-dawn.png","/images/petsteps-otd-day.png","/images/petsteps-otd-dusk.png","/images/petsteps-otd-night.png"]},{text:"A few things under the hood I am happy with. The daily step target comes from the 60th percentile of your recent history, so it moves with you instead of nagging you about a flat 10k. Coins get paid out through an idempotent daily ledger, which means no double paying when Health data syncs in late. The coach answers with on device Foundation Models when the phone supports them and falls back to rule based insights when it doesn't. Coins are also sold as a consumable through StoreKit 2."},{text:"The whole thing end to end in one take: onboarding, feeding and leveling, dress up, a live walk with the in-walk camera, and the journal."},{video:"/videos/petsteps/full_demo.mp4"},{text:"Built with SwiftUI (iOS 17+), SwiftData, HealthKit, CoreMotion, CoreLocation with MapKit for the routes, Swift Charts, StoreKit 2, and the iOS 26 Foundation Models framework. I'm planning an App Store release."}]},{id:"undertone",name:"Undertone",image:"/images/undertone-birds.gif",description:"Undertone is a Mac menu bar app I wrote to make my wallpaper move with whatever I'm listening to. It taps the system audio, pulls a palette off the album cover, and runs a single Metal shader that pulses on the beat. Paused, it idles at zero percent CPU. Playing, it costs about a millisecond of GPU a frame.",languages:["Swift","Metal","Core Audio","Accelerate"],tagline:"Beat synced Metal wallpaper for macOS",timeline:"2026",source:{label:"Full source code available upon request",href:"mailto:ximluo@upenn.edu?subject=Undertone%20code%20request"},links:[{label:"AudioFeatureKit",href:"https://github.com/ximluo/AudioFeatureKit"},{label:"ProcessTapKit",href:"https://github.com/ximluo/ProcessTapKit"},{label:"DesktopWindowKit",href:"https://github.com/ximluo/DesktopWindowKit"}],sections:[{text:"Every palette comes out of the album cover. I cluster the artwork's pixels in Oklab, which keeps the colors true as they merge, and I weight each one by how vivid it is, so a small burst of saturated color can outrank a big flat background. A Billie Eilish track lands in deep blue. Skyfall comes out gunbarrel teal. Same field, two songs:"},{images:["/images/undertone-birds.gif","/images/undertone-skyfall.gif"]},{text:"There are two modes. Static sets one still image per track and leaves it there. Dynamic is the live one above. Three styles ship with it, Aurora, Mesh, and Deep, and it all runs from a menu bar panel with an intensity slider, a flow slider that spans a slow drift up to about twenty times that speed, and a live CPU readout. The three styles on one song, plus the panel:"},{images:["/images/undertone-aurora.gif","/images/undertone-mesh.gif","/images/undertone-deep.gif","/images/undertone-ui.jpg"]},{text:"Hearing the music took the longest. Spotify closed their audio analysis API to new apps in late 2024, and the good open source audio libraries are all GPL, so I wrote the DSP myself. A Core Audio process tap picks the audio up straight from the OS, which keeps the install to dragging one app over, and from there it's an FFT, spectral flux for onsets, autocorrelation for tempo, and a phase locked loop on top. The loop predicts where the next beat will land, which matters because reacting to a beat lands about 60ms late and reads as sloppy. It also shifts for speaker latency, since the tap hears the audio a moment before your ears do."},{text:"All the motion runs on springs. Every beat kicks one, so the field contracts, overshoots into an expansion, and rings down in time with the tempo. Bigger hits add a lean that alternates direction each time, so the whole thing rocks back and forth. A momentum value builds through a long section and folds in a slow kneading distortion, so a chorus keeps escalating the longer it runs. How dramatic all of it gets follows a danceability number I compute from how clear and steady the beat is, measured so loudness stays out of it: an orchestral swell stays ambient, club music goes off."},{text:"The shader is a single full screen pass at half resolution, and the compositor scales it back up for free. The app suspends itself the moment the desktop gets covered, the screen locks, or you unplug and drop to battery, and it sits at a true zero percent CPU once the music stops. Quit it and your original wallpaper comes back. Running live, it costs around five percent CPU."},{text:"I pulled three reusable pieces out into their own MIT licensed Swift packages. [AudioFeatureKit](https://github.com/ximluo/AudioFeatureKit) is the real time beat and feature extractor, with a synthetic signal test suite. [ProcessTapKit](https://github.com/ximluo/ProcessTapKit) wraps the Core Audio tap and writes down every way I found it to fail silently. [DesktopWindowKit](https://github.com/ximluo/DesktopWindowKit) manages the window that lives behind your desktop icons across displays. The app itself stays private, and I'm happy to send the source on request."},{text:"Built in Swift with one Metal fragment shader, Core Audio process taps for capture, Accelerate for the FFT, and SwiftUI for the menu bar panel. It runs unsandboxed, so it ships as a notarized download outside the Mac App Store."}]},{id:"pennos",name:"PennOS",image:"/images/pennos-hero.gif",description:"PennOS is a UNIX-like operating system written from scratch in C. The entire OS runs inside a single Linux process: a kernel that context switches its own threads with ucontext, a weighted priority scheduler driven by a 100ms SIGALRM tick, a FAT filesystem that lives inside one disk image file, and a shell with bash-style job control on top. User land never touches the host: everything goes through our own syscall layer, s_spawn, s_waitpid, s_kill, s_open and friends, and the kernel logs every scheduling and lifecycle event it makes.",languages:["C","POSIX signals","ucontext"],tagline:"UNIX-like OS from scratch in C",timeline:"2026",sections:[{text:"This is a real session, not a mockup. Left side is the PennOS shell: create a file on the PennFAT disk, redirect into it, read it back, put a sleep and a busy loop in the background, list processes and jobs, kill one. Right side is the kernel's own log of the same moments: every CREATE, SCHEDULE, BLOCKED, ZOMBIE and WAITED transition as it happens."},{image:"/images/pennos-session.png"},{text:"The scheduler keeps three round-robin queues and steps them on a 100ms SIGALRM tick, weighted so queue 0 runs 1.5x as often as queue 1 and 2.25x as often as queue 2. When nothing is runnable it parks in sigsuspend, so an idle OS costs nothing. Spawn three busy loops at the three priorities and the schedule trace shows the weighting directly:"},{image:"/images/pennos-scheduler.png"},{text:"Processes get the full UNIX lifecycle. Parents block in s_waitpid, exited children hang around as zombies until someone reaps them, orphans get reparented to init, and init loops reaping whatever lands on it. Our own signals, P_SIGSTOP, P_SIGCONT and P_SIGTERM, drive stop and continue, and the shell traps the host's Ctrl+C and Ctrl+Z and forwards them to the foreground PennOS job, so jobs, fg, bg and nice behave the way bash trained your hands to expect."},{text:"The filesystem is PennFAT, a FAT-style filesystem that lives inside an ordinary host file. A standalone tool formats and inspects images, and the kernel mounts one at boot. On top of it sit per-process file descriptor tables, s_open, s_read, s_write and s_lseek, permissions, shell redirection, and script files that live on the PennFAT disk and execute like programs."}]},{id:"next",name:"NEXT",image:"/images/next-hero.png",description:"NEXT is a mobile app concept that helps students use the small gaps in their day. It asks how you feel and how much time you have, then hands you one thing to start. I designed it end to end as a UX case study, from a 22-person survey through wireframes, usability testing, and a full design system.",languages:["Figma","UX Research","UI Design","FigJam","Prototyping"],tagline:"A UX case study on deciding what to do next",timeline:"2026",links:[{label:"Full case study in Figma",href:"https://www.figma.com/proto/05Ye2LE3YLFaL3cRg4B0Dh/Ximing-Luo---Design?node-id=144-38"}],sections:[{text:"It started with watching how a free hour actually goes. You get out of class with fifty minutes before the next thing, you open your phone to figure out what to do with it, and you look up and the fifty minutes are gone. A senior I interviewed put it best: \u201cMy to-do list tells me everything, but not what is the best thing to do right now.\u201d"},{text:"I surveyed 22 students and interviewed a few more about where their gaps go. The thing that kept coming up is that deciding is the expensive part. Everyone already has a calendar and a to-do list, and both of them hand the choice back to you, which is exactly the moment you fall into your phone. Energy mattered more than time too, since a free hour when you're drained is a different hour. So the app narrowed to one job: make the decision cheap."},{text:"The wireframes existed to answer one question, whether the core loop holds up. Open the app, see a couple of suggestions, start one."},{image:"/images/next-wireframes.png"},{text:"The finished loop starts with your day laid out so the gaps are visible. Tap an open slot and it asks how you feel, then hands you a best fit plus two alternates, weighted by where you are and how long the walk to your next event takes. If the library book return is on your way, that beats the homework. Left to right, the schedule, the mood check, and the suggestions:"},{phoneImages:["/images/next-schedule.png","/images/next-mood.png","/images/next-suggestions.png"]},{text:"Pick one and focus mode takes over: a countdown ring, the apps you asked to be locked listed underneath, and a quiet switch task option for when you picked wrong. Finishing gives you the streak and a break worth taking rather than confetti, and at nine the app closes the day out with where your time went, how you felt across it, and what your friends are doing. Focus, completion, and the daily wrap up:"},{phoneImages:["/images/next-focus.png","/images/next-complete.png","/images/next-wrapup.png"]},{text:"Testing reshaped it more than once. Every tester treated the first version's scrollable feed of suggestions like a menu and picked nothing, which is how it became a single recommendation with a couple of alternates. Focus mode needed an exit that felt okay to use, so switching tasks became its own quiet action. The wrap-up went from a stats screen people closed immediately to a story about the day, with your friends at the bottom still going."},{text:"Since the whole product is about lowering the cost of a decision, the visual system had to stay out of the way. It borrows from paper more than from productivity software. Warm cream with espresso text and a honey accent, soft hues for the goal categories, and Inter in two weights, which forces hierarchy to come from size and spacing. Testers described it as feeling like a journal, which was the register I wanted."},{image:"/images/next-design-system.png"},{text:"The whole flow comes to nineteen screens, onboarding and calendar sync through achievements and profile. Here's the welcome screen and the social layer:"},{phoneImages:["/images/next-welcome.png","/images/next-achievements.png"]},{text:"Designed and written in Figma and FigJam, tested with three users on top of the 22 survey responses. The full case study, with all the research and iterations, is in the [Figma prototype](https://www.figma.com/proto/05Ye2LE3YLFaL3cRg4B0Dh/Ximing-Luo---Design?node-id=144-38)."}]},{id:"mini-minecraft",name:"Mini Minecraft",image:"/images/mini-minecraft.gif",description:"Custom built 3D voxel game engine inspired by Minecraft, featuring procedural terrain, day night cycles, dynamic lighting, instanced rendering, and a post processing pipeline. I implemented the player physics, raycast based block interaction, and immersive visual effects such as a time interpolated sky with sun arcs, distance fog blending, and a post process system for water and lava overlays.",languages:["C++","OpenGL","GLSL"],tagline:"C++ voxel game engine",timeline:"2024",sections:[{video:"https://www.youtube.com/embed/kr7ze2p7Tx8?si=f6Pqu8gN6oUHypdi"},{text:"A 3D voxel game engine inspired by Minecraft, built with C++ and OpenGL. It features procedural terrain generation, efficient chunk streaming, day night lighting, and a custom shader pipeline."},{text:"Physics system supports flying and grounded movement, with gravity, acceleration, and collision detection. Collisions are handled per axis for smooth sliding. Precise block interaction using ray casting from the camera, enabling players to mine and place blocks with pixel accuracy."},{text:"For the day night cycle, procedurally animated the sun\u2019s arc and sky color using GLSL, interpolating between time intervals to simulate realistic transitions. Lighting was synced with the sun\u2019s direction and color. Distance based fog adjusts dynamically to sky hues using smoothstep blending, creating a seamless atmospheric fade at horizon level."},{text:"Cave generation system using 3D Perlin noise, populating underground layers with air pockets, lava pools, and bedrock. Optimized sampling by bounding height ranges during development. Post processing pipeline to tint the screen when entering water or lava, using framebuffer textures and fullscreen shaders."}]},{id:"relight",name:"Relight",image:"/images/relight.gif",description:"Relight is a local web app that turns one photo into a relightable art reference. It cuts out the subject, estimates depth and surface normals, and splits color from shading, then lets you drag lights around the subject in real time in the browser. When the lighting feels right, a diffusion pass makes it photoreal. I built it because finding a reference photo with the exact lighting you want is basically impossible, so now I make it instead.",languages:["Python","PyTorch","TypeScript","WebGL"],tagline:"Diffusion relighting for art reference",timeline:"2026",source:{label:"Source code upon request",href:"mailto:ximluo@upenn.edu?subject=Relight%20code%20request"},sections:[{images:["/images/relight-final-koala2.png","/images/relight-input-koala.png"]},{text:"One flat photo goes in. The app rebuilds enough of the scene to light it again: what the subject is, how far away everything sits, which way each surface faces, and what color things are before light touches them. The koala above was shot in flat daylight and relit by moonlight. Here is the whole pipeline, step by step."},{text:"Step 1: understand the photo. [BiRefNet](https://arxiv.org/abs/2401.03407) cuts out the subject, [Depth Anything V2](https://arxiv.org/abs/2406.09414) estimates depth, [DSINE](https://arxiv.org/abs/2403.00712) estimates surface normals, and an intrinsic decomposition separates albedo from shading. Four maps, and the photo stops being flat:"},{images:["/images/relight-step-mask.png","/images/relight-step-depth.png","/images/relight-step-normals.png","/images/relight-step-albedo.png"]},{text:"Step 2: light it live. The browser relights everything at 60 fps in one WebGL fragment shader: up to four draggable lights, HDRI ambient, and a posterize mode that collapses the image into a 2 or 3 value study. Moving a cool key light around the koala:"},{images:["/images/relight-ui.png","/images/relight-sweep.gif"]},{text:"Step 3: make it real. The viewport is a fast approximation, so the final pass hands everything to [IC-Light](https://github.com/lllyasviel/IC-Light), a diffusion model that relights from the cutout. Diffusion drifts if you let it, and my early renders came back as a different subject entirely, so I keep it honest: the exact preview on screen becomes its starting image, that image gets biased toward the key light direction so the light lands where I put it, and the prompt matches the mood of the scene so a dark viewport stays dark. A second pass upscales and sharpens the details. The shaded preview on the left becomes the render on the right:"},{images:["/images/relight-preview-koala.png","/images/relight-final-koala2.png"]},{text:"Here is the process on another image:"},{images:["/images/relight-input-lion.png","/images/relight-lion-cutout.png","/images/relight-lion-depth.png","/images/relight-lion-normals.png"]},{images:["/images/relight-lion-sweep.gif","/images/relight-final-lion.png"]},{text:"It does more than one subject too: pull a cutout in from a second photo, click to add or refine masks with SAM 2, drop in a background that relights to match, and steer the final render with pieces of your own artwork."},{text:"Built in Python and TypeScript: a FastAPI backend runs BiRefNet, Depth Anything V2, DSINE, SAM 2 and IC-Light through PyTorch on Apple Silicon, and the frontend is Three.js with a single GLSL shader. A photo processes in about 10 seconds and a final render takes about a minute on an M2."}]},{id:"painterly",name:"Painterly",image:"/images/painterly.gif",heroAlign:"bottom",description:"Painterly is a stroke based renderer that turns a photo into a painting the way an artist would make one. It plans about ten thousand brush strokes with classical graphics techniques, understands the scene with computer vision models for depth and saliency, then paints in a human order: a light construction sketch, a wash, the subject before the background, faces coarse to fine with the eyes sharpest. The output is a finished painting plus a build up timelapse of every stroke.",languages:["Python","OpenCV","PyTorch"],tagline:"Photo to painting with computer vision",timeline:"2026",source:{label:"GitHub",href:"https://github.com/ximluo/painterly"},sections:[{images:["/images/painterly-bridge.gif","/images/painterly-input-bridge.png"]},{text:"Every frame is real strokes landing on a canvas. There is no neural style transfer and no video model: the timelapse on the left is painted from the photo on the right, and the same photo and seed always reproduce the same painting, byte for byte. Below is how one painting comes together, step by step."},{text:"Step 1: see the scene. Computer vision decides where detail will go before a single stroke is planned. [Depth Anything V2](https://arxiv.org/abs/2406.09414) estimates monocular depth (left) and a [BiRefNet](https://arxiv.org/abs/2401.03407) matte isolates the subject (right). Depth is quantile bucketed into paint groups, saliency promotes the subject to the top group, and YuNet face detection with eye landmarks marks where the finest brushes will work."},{images:["/images/painterly-step-depth.png","/images/painterly-step-matte.png"]},{text:"Step 2: sketch, wash, block in. A light gray construction sketch of long straight rough lines opens the painting (left), restated with hand wobble and mocked pen pressure, including the occasional wrong line that gets undone \u2014 guided by how process datasets like [Paints-UNDO](https://github.com/lllyasviel/Paints-UNDO) and [Time-Map](https://cragl.cs.gmu.edu/timemap/) show artists actually start. It lives on an overlay and disappears only where paint physically covers it, tracked by a per pixel cover map rather than a timer. A thin wash then tones the paper under the drawing and the block in begins (right): the engine modernizes Hertzmann's [Painterly Rendering with Curved Brush Strokes of Multiple Sizes](https://www.dgp.toronto.edu/papers/aherzmann_SIGGRAPH1998.pdf) (SIGGRAPH 1998), five brush radii painting coarse to fine, each layer seeding strokes only where the canvas still differs from the photo blurred at brush scale. The subject base coat goes down before the background gets anything."},{images:["/images/painterly-step-sketch.png","/images/painterly-step-blockin.png"]},{text:"Step 3: faces first, detail in patches. Faces render coarse to fine with the eyes leading while loose block in strokes keep the rest of the canvas growing (left), so the face is always the most detailed region at any moment of the timelapse. Bodies refine through anatomical zones instead of concentric rings, small brushes finish one patch before moving to the next, finished faces are protected by per face masks so no later stroke can smear them, and a few bright accents close the painting (right)."},{images:["/images/painterly-step-face.png","/images/painterly-painting-bridge.png"]},{text:"Step 4: the strokes themselves. Raw Hertzmann strokes meander like worms, so each one is rebuilt: its spine grows along an Edge Tangent Flow field ([Kang, Lee and Chui, Coherent Line Drawing, NPAR 2007](https://dl.acm.org/doi/10.1145/1274871.1274878)) so neighbors stay locally parallel, gets collapsed to a single quadratic Bezier with a 60 degree turn budget \u2014 the stroke parameterization used by neural painters like [Paint Transformer](https://arxiv.org/abs/2108.03798) (ICCV 2021) and [Stylized Neural Painting](https://arxiv.org/abs/2011.08114) (CVPR 2021) \u2014 and renders as a tapered bristle textured ribbon, wet mixed with the paint underneath. Width and opacity taper on Plamondon's lognormal velocity profile, and width trades against curvature per the [two thirds power law](https://pubmed.ncbi.nlm.nih.gov/6666128/)."},{text:"It took 23 versions to get the process right. Below, the first working version next to the final one, same engine skeleton and same photo: strokes wandered, the sketch was machine perfect, detail rained in randomly, and every region got the same treatment. The flow field, the Bezier turn budget, pressure tapered ribbons, the painter's ordering, and the depth masks are the difference."},{images:["/images/painterly-v1.gif","/images/painterly-cat.gif"]},{text:"And in stills, the before and after: the photo it was given, and the painting it left behind."},{images:["/images/painterly-input-cat.jpg","/images/painterly-painting-cat.png"]},{text:"It generalizes past portraits, since subject first ordering and depth grouping come from the models rather than hand tuning. The swan below is painted from the photo beside it."},{images:["/images/painterly-swan.gif","/images/painterly-input-swan.png"]},{text:"Built in Python with OpenCV for all stroke planning and rendering, PyTorch for Depth Anything V2, and ONNX Runtime for BiRefNet and YuNet. Cross platform: GPU acceleration uses Apple Silicon MPS or CUDA when available, with a CPU fallback. A 1080p painting renders with its timelapse in about a minute."}]},{id:"penn-mobile",name:"Penn Mobile",image:"/images/mobile.png",description:"Penn Mobile is the University of Pennsylvania\u2019s official student life app, serving 20,000+ users. Developed by Penn Labs, it brings campus essentials like dining hours, GSR reservations, laundry availability, and student resources directly to students\u2019 phones.",languages:["Swift","SwiftUI"],tagline:"Official Penn student app",timeline:"2025-Present",sections:[{text:"Learn more at [pennlabs.org/products/penn-mobile](https://pennlabs.org/products/penn-mobile)."},{text:"With Penn Mobile, students can reserve study rooms across campus, view dining hall menus and hours, check real time laundry availability, and access essential university resources, all from one centralized app."},{text:"Features include push notifications for upcoming reservations, daily laundry activity graphs, campus wide contact info, access to the Daily Pennsylvanian feed, and more. It\u2019s designed to make campus life easier, faster, and more mobile friendly."}]},{id:"rewind",name:"Rewind",image:"/images/rewind.png",description:"Rewind is an AR memory recall app that won the InterSystems Challenge at HackMIT 2024, integrated with the Apple Vision Pro. It uses Gaussian splatting for 3D scene generation and a LangChain based RAG pipeline with InterSystems IRIS Vector Search for natural language memory queries.",languages:["WebXR","LangChain","IRIS Vector Search"],tagline:"HackMIT Winner - AR memory",timeline:"2024",sections:[{text:"Gaussian Splatting 3D Scene Generation: We convert user video clips into point cloud environments using a custom Python pipeline and render them in real time with Three.js and WebXR. Users can navigate their memories in 360 degree AR."},{text:"Backend Architecture: The Flask API manages user sessions, stores memory metadata in a relational SQL database, and coordinates scene jobs. Each memory record includes timestamps, tags, and AR scene links."},{text:"RAG with Vector Search: We embed memory metadata and textual notes into vectors using LangChain embedding models. These vectors are indexed in InterSystems IRIS Vector Search. At query time, user questions are embedded, top K matching memories are retrieved, and the app surfaces exact moments, for example, \u201cShow my graduation day\u201d."}]},{id:"neuroscent",name:"NeuroScent",image:"/images/neuroscent.jpg",description:"NeuroScent is an XR biofeedback system that promotes mental wellbeing, combining olfaction, vision, and biosensing. Built for MIT Reality Hack 2025, it won the Hardware: Smart Sensing prize and Best Use of OpenBCI.",languages:["C#","Unity","Arduino","Fusion 360"],tagline:"MIT Reality Hack Winner - XR biosensing",timeline:"2025",sections:[{text:"NeuroScent integrates scent delivery and physiological sensing to extend XR immersion beyond vision and sound. We used the Varjo headset for visual feedback and OpenBCI Galea for EEG, PPG, and EMG biosignals, creating a holistic biofeedback loop."},{text:"The system captures EEG, EMG, and heart rate data from Galea, analyzes real time mental state, and triggers adaptive scent releases and visual effects to guide users toward calm or focus."},{text:"Harvested ultrasonic atomizers from consumer diffusers, controlled them with relays on an ESP32, and designed a Fusion 360 airflow chamber. Inspired by [Nebula: An Affordable Open Source and Autonomous Olfactory Display for VR Headsets](https://hal.science/hal-03838757v1/file/Nebula_VRST_2022%20%281%29.pdf), built a compact olfactory module."},{text:"In Unity, C# scripts stream Galea biosignals over USB serial. Shader Graph, particle systems, and animation scripts map biofeedback thresholds to scent and visual triggers in real time."},{video:"https://player.vimeo.com/video/1059625069"},{text:"Optimized performance by reducing draw calls, enabling occlusion culling, and using Unity URP with baked lighting. Simplified geometry and LOD management maximizing FPS on Varjo Aero."},{text:"Next steps include expanding immersive sequences, adding more scent channel permutations, and exploring clinical applications like patient relaxation during anesthesia with targeted biofeedback driven scent delivery."}]},{id:"penn-capsule",name:"Capsule",image:"/images/capsule-open.gif",description:"Penn Capsule transforms photo collections into interactive 3D time capsules that unlock on a specified date. Users customize capsule appearance, upload memories, and later experience a dynamic timelapse of their photos in a 3D environment.",languages:["AWS S3","Node.js","TypeScript","MongoDB"],tagline:"3D photo capsule app",timeline:"2025",sections:[{text:"On the frontend, React Three Fiber renders the 3D capsules. Capsules animate open, revealing embedded photos arranged chronologically around the interior. Users interact via orbit controls in an immersive 3D view."},{text:"On the backend, handle file uploads server side to AWS S3 via the AWS SDK, define MongoDB collections for Users and Time Capsules using the native driver, secure routes with JWT, and enable Google OAuth single sign on."},{image:"/images/capsule-upload.gif"},{text:"Upload memories into a capsule by drag and drop or file picker. Each upload is handled on the server and streamed directly to S3 before metadata is recorded."},{text:"Toggle view switches between traditional list layout and 3D capsule gallery. Real time previews animate in WebGL using Spline imported scenes."},{text:"Create a new capsule by specifying a name, unlock date, and visual theme. The API returns capsule data which the UI immediately renders via React state."},{image:"/images/capsule-customize.gif"},{text:"Customize appearance with a decorator service. Color filters are applied to capsule textures."},{image:"/images/capsule-open.gif"},{text:"Open a capsule to see all memories."},{video:"/images/PennCapsule.pdf"}]},{id:"gpu-path-tracer",name:"Monte Carlo Path Tracer",image:"/images/monte-carlo.png",description:"An offline Monte Carlo path tracer implemented in C++. Supports multiple integrators, area and point lights, BxDF models, depth of field, and a custom ray intersection engine.",languages:["C++","OpenGL","GLSL"],tagline:"C++ Monte Carlo renderer",timeline:"2025",sections:[{text:"This path tracer solves the light transport equation on the GPU using Monte Carlo integration, with a flexible framework for different sampling strategies and material models."},{text:"Global Illumination Integrator: The full integrator combines the MIS direct integrator with indirect bounces at each path vertex. By adding environment and interreflection contributions, it converges to a physically accurate result faster than the naive approach."},{image:"/images/pathtracer-cornell-area.png"},{text:"Cornell Box with Area Light: Uniformly sampling the ceiling light produces soft, realistic shadows and subtle red green light bleeding on the walls and floor."},{image:"/images/pathtracer-cornell-env.png"},{text:"Cornell Box with Environment Lighting: Without explicit lights, the environment map alone illuminates the scene. Multiple importance sampling ensures smooth, low variance results."},{image:"/images/pathtracer-cornell-spotlight.png"},{text:"Cornell Box with Spotlight: A cone shaped light source uses importance sampling within its solid angle for focused illumination and natural falloff."},{image:"/images/monte-carlo.png"},{text:"Earth Scene: An Earth and a moon lit by a distant environment map, rendered with the full integrator. Soft shadows, realistic color bleeding, and ambient illumination demonstrate the combined direct and indirect lighting."},{image:"/images/pathtracer-cornell-glass.png"},{text:"Cornell Box with Glass Ball: This scene adds a refractive glass sphere. Fresnel reflectance and transmission are computed per Schlick\u2019s approximation, resulting in realistic caustics and subtle light bending."},{image:"/images/pathtracer-global.png"},{text:"The tracer supports Lambertian diffuse, microfacet specular with GGX distribution, and refractive BxDFs. Glass like materials simulate both reflection and refraction via Fresnel equations."},{text:"Depth of field implemented with a thin lens camera model. Rays originate from a disk aperture and converge on the focal plane, producing natural focus blur. Built atop a custom ray intersection framework with Camera, Shape, and Primitive classes. Russian roulette termination and configurable bounce limits prevent runaway computation. Below are some more integrator examples:"},{text:"Naive Integrator: The simplest integrator casts random hemisphere samples at each bounce and returns lighting only when a ray directly hits a light source. Renders converge very slowly and show noticeable grain at low sample counts."},{image:"/images/pathtracer-naive.png"},{text:"Direct Lighting Integrator: This version samples scene lights explicitly, choosing random points on area or point lights to compute direct contributions. Shadows and highlights are crisp, but indirect bounces are not accounted for."},{image:"/images/pathtracer-direct.png"},{text:"Multiple Importance Sampling Integrator: To reduce variance across lights and materials, this integrator blends BSDF sampling with light sampling via the power heuristic. It produces cleaner direct lighting and fewer noise artifacts on glossy surfaces. Compare the results of MIS (left) with Naive Integrator only (center) and with Direct Integrator only (right)."},{image:"/images/pathtracer-mis.png"}]},{id:"pbr-renderer",name:"Real time Physically Based Renderer",image:"/images/pbr.png",description:"A real time shading project from Penn\u2019s Advanced Rendering course. Implements the energy conserving Cook Torrance microfacet BRDF using the Trowbridge Reitz GGX distribution, Schlick\u2019s Fresnel approximation, and the Smith Schlick GGX geometry term.",languages:["C++","GLSL","OpenGL"],tagline:"Real time PBR renderer",timeline:"2025",sections:[{text:"The PBR shader screenshot shows the microfacet model in action. Metallicness is toggled between zero and one via GUI sliders, and roughness is held around 0 to illustrate reflectiveness."},{image:"/images/pbr-gui.png"},{text:"All lighting and material calculations run in the fragment shader. Material properties like albedo, metallicness, and roughness are sampled from textures when available or controlled with GUI sliders otherwise."},{text:"Image based lighting uses two precomputed cubemaps: one for diffuse irradiance and one for glossy irradiance. The shader samples the diffuse map using surface normals and the glossy map using the reflected view vector."},{image:"/images/pbr-displacement.png"},{text:"Vertex displacement is driven by a height map in the vertex shader. Vertices are offset along interpolated normals before tangent space normal mapping adds fine surface detail."},{image:"/images/pbr-albedo.png"},{text:"When a model provides its own albedo texture, the shader samples its base color and feeds it into both the Lambertian diffuse irradiance and Cook Torrance specular equations for accurate material appearance."},{text:"The renderer maintains full refresh rates without dropped frames, demonstrating that even with PBR and displacement, real time performance is achievable."},{text:"For full implementation details, see [Real Shading in Unreal Engine 4](https://cdn2.unrealengine.com/Resources/files/2013SiggraphPresentationsNotes-26915738.pdf)."},{text:"Beyond the core PBR pipeline, two advanced rendering features were developed as course extensions."},{text:"Deferred Rendering and Screen Space Reflection: A multi pass deferred pipeline first renders scene attributes into a G buffer with attachments for albedo, world space normals, specular, and depth. The SSR pass reconstructs view space positions and normals, reflects view vectors, and performs iterative ray marching in screen space to sample G buffer data. A binary search refines intersection points before separable Gaussian blur applies glossy falloff. The final composite blends these reflections with direct Cook Torrance lighting."},{image:"/images/pbr-ssr.png"},{text:"Signed Distance Fields and Subsurface Scattering: A ray marched SDF shader steps along view rays using the sceneSDF composed of primitive SDF operations. Upon hit detection, the Cook Torrance BSDF calculates local lighting. Subsurface scattering uses a thinness metric computed via opposite direction SDF queries to attenuate light transmitted through the material, blended with diffuse irradiance for translucent effects. Scene repetition applies SDF repetition functions to clone the building elements across the environment."},{image:"/images/sdf-sub.png"}]}],...[{id:"web-experiments",name:"Web Exploratorium",image:"/images/web-tv.gif",description:"Web Exploratorium is a playground of mini interactive experiments built with React Three Fiber and Vite. Explore a 3D TV model with clickable hotspots that launch creative demos powered by p5.js and smooth CSS animations.",languages:["JavaScript","Vite","React Three Fiber"],tagline:"Interactive web experiments",timeline:"",sections:[{image:"/images/web-zoom.gif"},{text:"The main interface is a 3D TV rendered with React Three Fiber. Hovering circles indicate demos. Click to zoom into each screen. Screen content textures drive camera positioning calculations for smooth transitions."},{text:"Dive into the demos on the live site: [Web Exploratorium Live](https://artofthewebxl.github.io)"},{image:"/images/web-maze.gif"},{text:"Maze Generation leverages recursive backtracking in p5.js to carve perfect mazes on a grid. Real time animation shows the algorithm exploring and backtracking."},{image:"/images/web-tree.gif"},{text:"Procedural Tree Generation uses p5.js and recursion to draw branching fractals. Adjustable parameters let users explore infinitely varied tree structures."},{image:"/images/web-gallery.gif"},{text:"The CSS Image Gallery features smooth transitions and hover effects. Thumbnails expand and slide fluidly using CSS variables and keyframe animations."},{image:"/images/web-clock.gif"},{text:"Pixel Clock is a canvas based timepiece built in p5.js."},{image:"/images/web-ascii.gif"},{text:"Using the characters in the Chinese phrase, \u51b0\u5c71\u4e00\u89d2 (b\u012bng sh\u0101n y\u012b ji\u01ceo), which means \u201cThe tip of an iceberg\u201d, to create an image of an iceberg. Part of the image should be hidden, which reflects the meaning of the phrase."},{image:"/images/web-still.gif"},{text:"The CSS still life showcases an animated still life composition created using CSS."}]},{id:"lost-at-penn",name:"Lost@Penn",image:"/images/lost.png",description:"Lost@Penn is a web platform that helps the Penn community report and find lost items across campus. Built with React.js, Firebase, and Tailwind, it offers a centralized, easy to use solution to a common student problem. Through user research and iterative design, we created a trustworthy and intuitive platform focused on usability and real needs.",languages:["React.js","Tailwind","Firebase"],tagline:"Penn lost item platform",timeline:"2024",sections:[{video:"https://www.youtube.com/embed/DxMMO6Qa638?si=4tPosHJ_6WKeH1kH"},{text:"Lost@Penn was inspired by the shared frustration of losing items on campus without knowing where to turn. There was no centralized system to report or search for missing belongings, so we set out to build one. We started by interviewing Penn students to understand the pain points and features they needed most."},{text:"Lost@Penn was built with React.js for its component based architecture, Firebase for backend services and real time syncing, Tailwind and Bootstrap for responsive design, and Figma for prototyping and iteration. We focused on building a fast, usable interface with strong visual hierarchy and minimal friction. From the user interviews to the final prototype, every step of the process was grounded in solving a real problem for a real community."},{text:"Read more at: [Lost@Penn Case Study](https://medium.com/@ximingluo/lost-penn-863d1706a193)"},{video:"/images/Lost-at-Penn.pdf"}]},{id:"vr-meta-quest-experiences",name:"Portals & DreamScape VR",image:"/images/vr.png",description:"Two immersive 360 degree VR experiences for Meta Quest 3 built in Unreal Engine 5.5. Both feature spatial audio, interactive elements, and NavMesh based locomotion: \u201cPortals through the Season\u201d with seamless level streaming portals; \u201cDreamScape\u201d with grabbable crystals in a mushroom forest.",languages:["Unreal Engine","Blueprints","C++"],tagline:"Meta Quest VR scenes",timeline:"2025",sections:[{text:"Portals through the Season presents a pair of themed levels connected by interactive portals. Entering a portal uses level streaming to load and unload environments instantly. UI widgets built in Blueprints animate activation rings and transition effects. NavMesh enables smooth player movement and teleportation."},{video:"https://www.youtube.com/embed/putNy1s3eL8?si=04OUckwGQPan_b4M"},{video:"/images/Portals.pdf"},{text:"DreamScape transports users to a 360 degree mushroom forest. Players can grab and place a crystalline artifact to trigger environmental changes. Spatialized ambient sounds and sound effects respond to proximity, and NavMesh driven locomotion ensures comfort during exploration."},{video:"https://drive.google.com/file/d/1vo85unb33cchrQF0wL8lFlqO5VpXHhL6/preview"},{video:"/images/DreamScape.pdf"}]},{id:"glsl-shaders",name:"GLSL Shaders",image:"/images/glsl-mosaic.png",description:"A collection of real time GLSL shaders written in C++ and OpenGL. Each shader demonstrates a different visual effect or lighting model, including vertex displacement, lighting, and post processing filters.",languages:["C++","OpenGL","GLSL"],tagline:"OpenGL shader collection",timeline:"2024",sections:[{image:"/images/glsl-inflate.gif"},{text:"Vertex Inflation: A custom vertex shader that offsets each vertex along its normal, creating an expanding puffed effect. The degree of inflation is adjustable in real time."},{image:"/images/glsl-mosaic.png"},{text:"Mosaic Filter: A fragment shader that divides the screen into a grid of tiles. Each tile samples the center pixel color and applies it uniformly across the tile area, creating a pixelated mosaic effect. The tile size is adjustable in real time."},{image:"/images/glsl-blinn.png"},{text:"Blinn Phong: Per fragment lighting using ambient, diffuse, and specular components. The half vector is used for more efficient specular reflection."},{image:"/images/glsl-blur.png"},{text:"Gaussian Blur: A separable 2 pass blur filter implemented in screen space, using a weighted kernel to smooth the scene."},{image:"/images/glsl-sobel.png"},{text:"Sobel: Edge detection filter that computes the gradient magnitude across screen space color values, highlighting high frequency detail."},{image:"/images/glsl-lambert.png"},{text:"Lambert: Basic diffuse lighting using the cosine of the angle between light and surface normal. Simple and efficient per fragment shading."},{image:"/images/glsl-chrome.png"},{text:"Matcap Chrome: Uses a normal based matcap texture lookup to create a reflective metallic appearance with no dynamic lighting."},{image:"/images/glsl-red.png"},{text:"Matcap Red Plastic: Simulates plastic like material using a matcap texture with strong specular highlights and soft shading transitions."}]}],...[{id:"statistical-learning-returns",name:"Machine Learning in Asset Pricing",image:"/images/wdrp.png",description:"This Wharton Directed Reading Program project investigates whether asset returns can be predicted using modern statistical learning methods. The research evaluates the efficiency of financial markets by applying both classical econometrics and advanced machine learning models to historical stock data.",languages:["Python","R"],tagline:"Wharton Directed Reading Program project",timeline:"2025",sections:[{text:"Wharton Directed Reading Program, April 24, 2025: MACHINE LEARNING IN ASSET PRICING. Exploring predictability in stock returns. Lead student: Ximing Luo (CS (DMD) and Economics \u201927). Mentor: Yiwen Lu (Finance PhD, 2nd Year)."},{text:"Introduction: Challenge. Despite the efficient market hypothesis asserting that prices reflect all available information, subtle anomalies persist. Motivation. Asset prices are dynamic predictions built on evolving data, and machine learning can uncover weak nonlinear signals without strict functional assumptions."},{text:"Background and Methodology: Reviewed efficient market hypothesis in weak, semi strong, and strong forms. Revisited the fundamental asset pricing equation and CAPM as a benchmark. Designed a hybrid workflow exploring econometric models such as linear regression, ARIMA, and factor models with modern ML such as penalized regression, tree based methods, feed forward and recurrent neural networks, and CNNs for chart image feature extraction."},{text:"Data, Analysis and Empirical Findings: Used historical prices, technical and fundamental signals, and alternative sources such as news sentiment and OHLC chart images. Extracted features via PCA, NLP topic models, and CNN embeddings. Trained and validated with pseudo out of sample cross validation. Modern ML models achieved higher out of sample R squared and improved trading metrics, revealing double descent behavior in overparameterized regimes."},{text:"Implications and Future Directions: Modern ML improves return predictability and informs adaptive long short strategies, risk forecasts, and real time integration of alternative data. Future work will deepen sentiment and image based features and develop hybrid frameworks that fuse economic theory with data driven predictions to better capture evolving market dynamics."}]},{id:"hci-research-jhu",name:"Human AI Interaction at JHU",image:"/images/hci.png",description:"Conducted research in the Intuitive Computing Laboratory under Dr Chien Ming Huang. Contributed to projects on two areas of human AI interaction: end to end co creation of visual stories with generative models, and apology strategies to mitigate errors in voice assistants.",languages:["Python","React.js"],tagline:"Human AI interaction research",timeline:"2022-2023",sections:[{text:"Contributed to two projects in the Intuitive Computing Lab at Johns Hopkins University, collaborating with PhD students Victor Nikhil Antony and Amama Mahmood. One project introduces an integrated authoring system for visual story creation using LLMs and multimodal generation. The other studies how apology tone and blame assignment affect user perceptions of voice assistants after recognition errors."},{text:"ID.8: Co Creating Visual Stories with Generative AI. Built an open source React system for a multi stage authoring workflow: collaborative script generation, automated scene parsing into storyboards, and asset creation with generative models. A human in control design keeps users in charge while AI accelerates iteration. User studies found strong usability and enjoyment and produced design guidance for prompt templates, iterative co creation, and consistent AI identity management. For details, see [ID.8: Co Creating Visual Stories with Generative AI](https://doi.org/10.1145/3672277)."},{text:"Owning Mistakes Sincerely: Strategies for Mitigating AI Errors. Ran an online study with a voice based shopping assistant that varied apology style and blame attribution after homonym recognition errors. A serious apology that accepts blame improved recovery satisfaction, perceived intelligence, and likeability, while blaming others could be worse than no apology. For details, see [Owning Mistakes Sincerely: Strategies for Mitigating AI Errors](https://doi.org/10.1145/3491102.3517565)."}]},{id:"ar-mri-point-cloud",name:"AR MRI Point Cloud Visualization",image:"/images/ar-mri.png",description:"Integrated pipeline automating conversion of patient brain MRIs into high quality 3D point cloud models for augmented reality. Enables collaborative visualization and annotation on Microsoft HoloLens head mounted displays.",languages:["Python","C#"],tagline:"AR MRI visualization pipeline",timeline:"2023-2025",sections:[{text:"This project streamlines a manual workflow of medical scan segmentation, mesh cleanup, and file conversion into a single web application. Physicians upload DICOM MRI sequences, automatically generate refined 3D point cloud models, and view or annotate them in real time on multiple AR headsets."},{text:"Pipeline steps include intensity threshold segmentation on 2D slices, outlier removal that drops points beyond 2.5 standard deviations from each anatomical centroid, and streaming the processed point cloud through a REST API into a Unity based Microsoft HoloLens app for immersive visualization, annotation, and manipulation."},{text:"Generated two complete point cloud models from brain MRI datasets and rendered them in AR, highlighting challenges with complex neuroanatomy. Ongoing work improves segmentation robustness, adds color coded segment views, and expands support for multi contrast MRI."},{text:"Worked with Dr. Chamith Rajapakse in Radiology and Orthopedics to optimize machine learning based MRI segmentation workflows in Python and C++ for 3D point cloud generation, and integrated real time AR visualization and annotation on Microsoft HoloLens 2 using Unity and C# for clinical diagnostics."}]}]],n=new Map(["mini-minecraft","pennos","undertone","penn-mobile","relight","petsteps","painterly","penn-capsule","rewind","neuroscent","gpu-path-tracer","pbr-renderer","web-experiments","lost-at-penn","statistical-learning-returns","hci-research-jhu","ar-mri-point-cloud","next","vr-meta-quest-experiences","glsl-shaders"].map(((e,t)=>[e,t]))),s=[...i].sort(((e,t)=>{var a,i;return(null!==(a=n.get(e.id))&&void 0!==a?a:Number.MAX_SAFE_INTEGER)-(null!==(i=n.get(t.id))&&void 0!==i?i:Number.MAX_SAFE_INTEGER)}))},4022:(e,t,a)=>{a.d(t,{A:()=>n});var i=a(5043);const n=function(){let{root:e=null,rootMargin:t,threshold:a,disabled:n=!1,initialValue:s=!1}=arguments.length>0&&void 0!==arguments[0]?arguments[0]:{};const[o,r]=(0,i.useState)(null),[l,d]=(0,i.useState)(s);return(0,i.useEffect)((()=>{if(n||l||!o)return;if("undefined"===typeof IntersectionObserver)return void d(!0);const i=new IntersectionObserver((e=>{e.some((e=>e.isIntersecting))&&(d(!0),i.disconnect())}),{root:e,rootMargin:t,threshold:a});return i.observe(o),()=>i.disconnect()}),[n,l,o,e,t,a]),{ref:r,hasIntersected:l}}},8540:(e,t,a)=>{function i(e){return/\.gif(?:$|[?#])/i.test(e)}a.d(t,{A:()=>i})}}]);
